193	    @Transactional
194	    public OrderShipment createOrderShipment(Order order, String receiverName, String receiverPhone,
195	                                             String postalCode, String address) {
196	        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
197	                order.getId(), receiverName);
198	
199	        OrderShipment shipment = OrderShipment.builder()
200	                .order(order)
201	                .receiverName(receiverName)
202	                .receiverPhone(receiverPhone)
203	                .postalCode(postalCode)
204	                .address(address)
205	                .status(ShipmentStatus.PENDING) // 초기 상태 설정
206	                .build();
207	
208	        OrderShipment savedShipment = orderShipmentRepository.save(shipment);
209	        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
210	                savedShipment.getId(), order.getId());
211	
212	        return savedShipment;
213	    }
