286	/**
287	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
288	 */
289	@Slf4j
290	@Configuration
291	@RequiredArgsConstructor
292	public class UpdateShipmentStatusesJobConfig {
293	
294	    private final JobRepository jobRepository;
295	    private final PlatformTransactionManager transactionManager;
296	    private final EntityManagerFactory entityManagerFactory;
297	
298	    private final OrderShipmentRepository orderShipmentRepository;
299	    private final NotificationCommandService notificationService;
300	    private final OrderShipmentCommandService orderService;
301	    private final CjTrackingPlaywright cjTrackingPlaywright;
302	
303	    private static final int CHUNK_SIZE = 50;
304	    private static final int SKIP_LIMIT = 50;
305	
306	    @Bean
307	    public Job updateShipmentStatusesJob() {
308	        log.info("배송 상태 업데이트 작업 구성");
309	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
310	                .start(updateShipmentStatusesStep())
311	                .build();
312	    }
313	
314	    @Bean
315	    public Step updateShipmentStatusesStep() {
316	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
317	
318	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
319	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
320	                .reader(shipmentItemReader())
321	                .processor(new ShipmentItemProcessor(
322	                        playwrightBrowserManager(), // Bean or new
323	                        notificationService,
324	                        orderService
325	                ))
326	                .writer(shipmentJpaItemWriter())
327	                .faultTolerant()
328	                .skip(Exception.class)
329	                .skipLimit(SKIP_LIMIT)
330	                .listener(shipmentSkipListener())
331	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
332	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
333	                .build();
334	    }
335	
336	    /**
337	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
338	     */
339	    @Bean
340	    @StepScope
341	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
342	        log.debug("배송 상태 업데이트 ItemReader 구성");
343	        return new JpaPagingItemReaderBuilder<OrderShipment>()
344	                .name("shipmentItemReader")
345	                .entityManagerFactory(entityManagerFactory)
346	                .pageSize(CHUNK_SIZE)
347	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
348	                .build();
349	    }
350	
351	    /**
352	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
353	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
354	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
355	     */
356	    @Bean
357	    @StepScope
358	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
359	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
360	
361	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
362	        return orderShipment -> {
363	            String trackingNumber = orderShipment.getTrackingNumber();
364	            Long shipmentId = orderShipment.getId();
365	
366	            if (trackingNumber == null || trackingNumber.isBlank()) {
367	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
368	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
369	            }
370	
371	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
372	                    shipmentId, trackingNumber, orderShipment.getStatus());
373	
374	            try {
375	                // 2-1) 현재 상태 가져오기
376	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
377	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
378	
379	                // 2-2) 매핑
380	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
381	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
382	
383	                // 현재 상태와 동일한 경우 중복 처리 방지
384	                if (orderShipment.getStatus() == newStatus) {
385	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
386	                            shipmentId, newStatus);
387	                    return orderShipment;
388	                }
389	
390	                // 2-3) 상태에 따른 처리
391	                if (newStatus == ShipmentStatus.DELIVERED) {
392	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
393	                            shipmentId, orderShipment.getOrder().getId());
394	
395	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
396	                    // Order 상태도 COMPLETED 로 변경
397	                    orderService.completeOrder(orderShipment.getOrder().getId());
398	                    // 알림 발송
399	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
400	                }
401	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
402	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
403	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
404	                    // 필요시 알림, 로직 추가
405	                }
406	                else {
407	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
408	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
409	                }
410	
411	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
412	                return orderShipment; // Writer로 넘김
413	
414	            } catch (Exception e) {
415	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
416	                        shipmentId, trackingNumber, e.getMessage(), e);
417	
418	                // ShipmentException 타입이 아닌 경우 래핑
419	                if (!(e instanceof ShipmentException)) {
420	                    throw new ShipmentException(
421	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
422	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
423	                            e
424	                    );
425	                }
426	                throw e;
427	            }
428	        };
429	    }
430	
431	    /**
432	     * CJ대한통운 배송 상태 조회를 위한 메서드
433	     *
434	     * @param trackingNumber 운송장 번호
435	     * @return 배송 상태 텍스트
436	     * @throws Exception 조회 실패 시 발생
437	     */
438	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
439	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
440	
441	        try {
