297	}package com.fream.back.domain.shipment.config;
298	
299	import com.fream.back.domain.notification.service.command.NotificationCommandService;
300	import com.fream.back.domain.shipment.entity.OrderShipment;
301	import com.fream.back.domain.shipment.entity.ShipmentStatus;
302	import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
303	import com.fream.back.domain.shipment.exception.ShipmentException;
304	import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
305	import com.fream.back.global.utils.PlaywrightBrowserManager;
306	import com.microsoft.playwright.Page;
307	import lombok.extern.slf4j.Slf4j;
308	import org.jsoup.Jsoup;
309	import org.jsoup.nodes.Document;
310	import org.jsoup.select.Elements;
311	import org.springframework.batch.item.ItemProcessor;
312	
313	/**
314	 * 배송 상태 배치 처리를 위한 ItemProcessor
315	 * 주문 배송 상태를 조회하고 처리합니다.
316	 */
317	@Slf4j
318	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
319	
320	    private final PlaywrightBrowserManager browserManager;
321	    private final NotificationCommandService notificationService;
322	    private final OrderShipmentCommandService orderService;
323	
324	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
325	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
326	    private static final int TIMEOUT_MS = 30000; // 30초
327	
328	    /**
329	     * 배송 상태 처리기 생성자
330	     *
331	     * @param browserManager Playwright 브라우저 관리자
332	     * @param notificationService 알림 서비스
333	     * @param orderService 주문 서비스
334	     */
335	    public ShipmentItemProcessor(
336	            PlaywrightBrowserManager browserManager,
337	            NotificationCommandService notificationService,
338	            OrderShipmentCommandService orderService
339	    ) {
340	        this.browserManager = browserManager;
341	        this.notificationService = notificationService;
342	        this.orderService = orderService;
343	    }
344	
345	    /**
346	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
347	     *
348	     * @param orderShipment 처리할 배송 정보
349	     * @return 업데이트된 배송 정보
350	     * @throws Exception 처리 중 오류 발생 시
351	     */
352	    @Override
353	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
354	        String trackingNumber = orderShipment.getTrackingNumber();
355	        Long shipmentId = orderShipment.getId();
356	
357	        if (trackingNumber == null || trackingNumber.isBlank()) {
358	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
359	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
360	        }
361	
362	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
363	                shipmentId, trackingNumber, orderShipment.getStatus());
364	
365	        Page page = null;
366	        try {
367	            // browserManager를 통해 페이지 생성
368	            page = browserManager.newPage();
369	            if (page == null) {
370	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
371	            }
372	
373	            // 타임아웃 설정
374	            page.setDefaultTimeout(TIMEOUT_MS);
375	
376	            // 배송 추적 URL로 이동
377	            String url = TRACKING_URL_PREFIX + trackingNumber;
378	            log.debug("배송 조회 페이지로 이동: {}", url);
379	            page.navigate(url);
380	
381	            // 배송 상태 테이블 로드 대기
382	            log.debug("배송 상태 테이블 로드 대기");
383	            page.waitForSelector(STATUS_SELECTOR);
384	
385	            // 최종 HTML 가져오기
386	            String renderedHtml = page.content();
387	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
388	
389	            // HTML 파싱하여 배송 상태 추출
390	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
391	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
392	
393	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
394	                    shipmentId, statusText, newStatus);
395	
396	            // 현재 상태와 동일한 경우 중복 처리 방지
397	            if (orderShipment.getStatus() == newStatus) {
398	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
399	                        shipmentId, newStatus);
400	                return orderShipment;
401	            }
402	
403	            // 상태에 따른 처리
404	            if (newStatus == ShipmentStatus.DELIVERED) {
405	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
406	                        shipmentId, orderShipment.getOrder().getId());
407	
408	                // 배송 상태 업데이트
409	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
410	
411	                // 주문 완료 처리 및 알림
412	                orderService.completeOrder(orderShipment.getOrder().getId());
413	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
414	
415	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
416	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
417	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
418	
419	            } else {
420	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
421	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
422	            }
423	
424	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
425	                    shipmentId, orderShipment.getStatus());
426	
427	            return orderShipment;
428	
429	        } catch (Exception e) {
430	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
431	                    shipmentId, trackingNumber, e.getMessage(), e);
432	
433	            // ShipmentException 타입이 아닌 경우 래핑
434	            if (!(e instanceof ShipmentException)) {
435	                throw new ShipmentException(
436	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
437	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
438	                        e
439	                );
440	            }
441	            throw e;
442	        } finally {
443	            // 페이지 리소스 해제
444	            if (page != null) {
445	                try {
446	                    page.close();
447	                    log.debug("페이지 리소스 해제 완료");
448	                } catch (Exception e) {
449	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
450	                }
451	            }
452	        }
453	    }
454	
455	    /**
456	     * HTML에서 배송 상태를 파싱합니다.
457	     *
458	     * @param html 파싱할 HTML 문자열
459	     * @param trackingNumber 로깅용 운송장 번호
460	     * @return 배송 상태 문자열
461	     * @throws ShipmentException 파싱 실패 시 발생
462	     */
463	    private String parseStatusFromHtml(String html, String trackingNumber) {
464	        try {
465	            Document doc = Jsoup.parse(html);
466	            Elements rows = doc.select(STATUS_SELECTOR);
467	
468	            if (rows.isEmpty()) {
469	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
470	                throw new ShipmentException(
471	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
472	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
473	                );
474	            }
475	
476	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
477	            String statusText = rows.last().select("td").get(4).text().trim();
478	
479	            if (statusText.isEmpty()) {
480	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
481	                throw new ShipmentException(
482	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
483	                        "배송 상태 정보를 찾을 수 없습니다."
484	                );
485	            }
486	
487	            return statusText;
488	
489	        } catch (IndexOutOfBoundsException e) {
490	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
491	            throw new ShipmentException(
492	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
493	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
494	                    e
495	            );
496	        } catch (Exception e) {
497	            if (e instanceof ShipmentException) {
498	                throw (ShipmentException) e;
499	            }
500	
501	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
502	            throw new ShipmentException(
503	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
504	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
505	                    e
506	            );
507	        }
508	    }
509	
510	    /**
511	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
512	     *
513	     * @param statusText 배송사 상태 텍스트
514	     * @return 매핑된 ShipmentStatus
515	     */
516	    private ShipmentStatus mapToShipmentStatus(String statusText) {
517	        return switch (statusText) {
518	            case "배송완료" -> ShipmentStatus.DELIVERED;
519	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
520	            default -> ShipmentStatus.IN_TRANSIT;
521	        };
522	    }
523	}

