 52	    @Transactional
 53	    public void processPaymentAndShipment(Long orderId, String userEmail, PayAndShipmentRequestDto requestDto) {
 54	        if (orderId == null) {
 55	            throw new InvalidOrderDataException("주문 ID가 없습니다.");
 56	        }
 57	        if (userEmail == null || userEmail.trim().isEmpty()) {
 58	            throw new OrderAccessDeniedException("사용자 정보가 없습니다.");
 59	        }
 60	        if (requestDto == null) {
 61	            throw new InvalidPaymentShipmentDataException("결제 및 배송 정보가 없습니다.");
 62	        }
 63	
 64	        try {
 65	            // 1. User 및 Order 조회
 66	            User user = userQueryService.findByEmail(userEmail);
 67	            Order order = orderRepository.findById(orderId)
 68	                    .orElseThrow(() -> new OrderNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
 69	
 70	            // 접근 권한 확인
 71	            if (!order.getUser().getId().equals(user.getId())) {
 72	                throw new OrderAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
 73	            }
 74	
 75	            // 주문 정보 유효성 검사
 76	            validatePaymentShipmentRequest(requestDto);
 77	
 78	            try {
 79	                // 2. 결제 처리
 80	                Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
 81	                order.assignPayment(payment);
 82	            } catch (Exception e) {
 83	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
 84	                throw new OrderPaymentProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
 85	            }
 86	
 87	            try {
 88	                // 3. 배송 정보 생성
 89	                OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
 90	                        order,
 91	                        requestDto.getReceiverName(),
 92	                        requestDto.getReceiverPhone(),
 93	                        requestDto.getPostalCode(),
 94	                        requestDto.getAddress()
 95	                );
 96	                order.assignOrderShipment(shipment);
 97	            } catch (Exception e) {
 98	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
 99	                throw new OrderShipmentProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
100	            }
101	
102	            try {
103	                // 4. 상태 업데이트
104	                if (requestDto.isWarehouseStorage()) {
105	                    // 창고 보관일 경우
106	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
107	                    order.updateStatus(OrderStatus.PREPARING);
108	                    order.updateStatus(OrderStatus.IN_WAREHOUSE);
109	
110	                    // 창고 보관 처리 추가
111	                    WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
112	                    order.assignWarehouseStorage(warehouseStorage);
113	                    order.updateStatus(OrderStatus.COMPLETED);  // 주문 완료 상태로 변경
114	                } else {
115	                    // 실제 배송일 경우
116	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
117	                    order.updateStatus(OrderStatus.PREPARING);
118	                }
119	            } catch (WarehouseStorageException e) {
120	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
121	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
