145	    /**
146	     * 즉시 구매 주문을 생성합니다.
147	     *
148	     * @param buyer 구매자 정보
149	     * @param saleBid 판매 입찰 정보
150	     * @param addressId 배송지 ID
151	     * @param isWarehouseStorage 창고 보관 여부
152	     * @param paymentRequest 결제 요청 정보
153	     * @return 생성된 주문
154	     * @throws OrderCreationFailedException 주문 생성 실패 시
155	     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우
156	     * @throws InvalidOrderDataException 주문 정보가 유효하지 않은 경우
157	     * @throws OrderPaymentProcessingFailedException 결제 처리 실패 시
158	     * @throws OrderWarehouseStorageProcessingFailedException 창고 보관 처리 실패 시
159	     */
160	    @Transactional
161	    public Order createInstantOrder(User buyer, SaleBid saleBid, Long addressId,
162	                                    boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
163	        try {
164	            // 입력값 검증
165	            if (buyer == null) {
166	                throw new InvalidOrderDataException("구매자 정보가 없습니다.");
167	            }
168	            if (saleBid == null) {
169	                throw new SaleBidNotFoundException("판매 입찰 정보가 없습니다.");
170	            }
171	            if (addressId == null) {
172	                throw new InvalidOrderDataException("배송지 정보가 없습니다.");
173	            }
174	            if (paymentRequest == null) {
175	                throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
176	            }
177	
178	            // 1. 주소 조회
179	            AddressResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
180	
181	            // 2. Order 생성
182	            Order order = Order.builder()
183	                    .user(buyer)
184	                    .totalAmount(saleBid.getBidPrice())
185	                    .status(OrderStatus.PENDING_PAYMENT)
186	                    .build();
187	
188	            order = orderRepository.save(order);
189	
190	            // PaymentRequest에 OrderId 설정
191	            paymentRequest.setOrderId(order.getId());
192	            log.debug("결제 요청 정보: {}", paymentRequest);
193	
194	            // 3. OrderItem 추가
195	            try {
196	                OrderItem orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
197	                order.addOrderItem(orderItem);
198	            } catch (Exception e) {
199	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
200	                throw new OrderItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
201	            }
202	
203	            // 4. 배송 정보 생성 및 연관 설정
204	            try {
205	                OrderShipment orderShipment = orderShipmentCommandService.createOrderShipment(
206	                        order,
207	                        address.getRecipientName(),
208	                        address.getPhoneNumber(),
209	                        address.getZipCode(),
210	                        address.getAddress()
211	                );
212	                order.assignOrderShipment(orderShipment);
213	            } catch (Exception e) {
214	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
215	                throw new OrderShipmentProcessingFailedException("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
216	            }
217	
218	            try {
219	                // 판매 입찰 상태 업데이트
220	                saleBid.assignOrder(order);
221	                saleBid.updateStatus(com.fream.back.domain.sale.entity.BidStatus.MATCHED);
222	
223	                // 변경 내용 강제 반영
224	                entityManager.flush();
225	            } catch (Exception e) {
226	                log.error("판매 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
227	                throw new OrderBidMatchingFailedException("판매 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
228	            }
229	
230	            // Sale의 isWarehouseStorage 확인 후 상태 변경
231	            try {
232	                Sale sale = saleBid.getSale();
233	                if (sale != null && sale.isWarehouseStorage()) {
234	                    warehouseStorageCommandService.updateWarehouseStatus(sale, WarehouseStatus.ASSOCIATED_WITH_ORDER);
235	                }
236	            } catch (WarehouseStorageException e) {
237	                log.error("창고 보관 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
238	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
239	            } catch (Exception e) {
240	                log.error("창고 보관 상태 업데이트 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
241	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
         // 1. 결제 처리
         Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
         order.assignPayment(payment);

         if (!payment.isSuccess()) {
             throw new RuntimeException("결제 실패: " + payment.getStatus());
         }

         log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());

         // 2. 배송 정보 생성
         OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
                 order,
                 requestDto.getReceiverName(),
                 requestDto.getReceiverPhone(),
                 requestDto.getPostalCode(),
                 requestDto.getAddress()
         );
         order.assignOrderShipment(shipment);
         log.info("배송 정보 생성 완료: 주문ID={}", order.getId());

         // 3. 상태 업데이트 (OrderStatus enum 사용)
         if (!order.getStatus().canTransitionTo(OrderStatus.PAYMENT_COMPLETED)) {
             throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
         }
         order.updateStatus(OrderStatus.PAYMENT_COMPLETED);

         if (requestDto.isWarehouseStorage()) {
             // 창고 보관일 경우
             WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
             order.assignWarehouseStorage(warehouseStorage);

             // 상태 전환 검증
             if (order.getStatus().canTransitionTo(OrderStatus.PREPARING)) {
                 order.updateStatus(OrderStatus.PREPARING);
             }
             if (order.getStatus().canTransitionTo(OrderStatus.IN_WAREHOUSE)) {
                 order.updateStatus(OrderStatus.IN_WAREHOUSE);
             }
             if (order.getStatus().canTransitionTo(OrderStatus.COMPLETED)) {
                 order.updateStatus(OrderStatus.COMPLETED);
             }

             log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
         } else {
             // 실제 배송일 경우
             if (order.getStatus().canTransitionTo(OrderStatus.PREPARING)) {
                 order.updateStatus(OrderStatus.PREPARING);
             }
             log.info("배송 준비 완료: 주문ID={}", order.getId());
         }

         // 4. 주문 저장
         orderRepository.save(order);
         log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());

     } catch (Exception e) {
         log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
         throw e; // 트랜잭션 롤백을 위해 예외 재발생
     }
 }

 /**
  * 주문이 이미 처리되었는지 확인 (멱등성 보장)
  */
 private boolean isOrderAlreadyProcessed(Long orderId) {
     try {
         Order order = orderRepository.findById(orderId).orElse(null);
         if (order == null) {
             return false;
         }

         // PENDING_PAYMENT 상태가 아니면 이미 처리된 것으로 간주
         OrderStatus currentStatus = order.getStatus();
         return currentStatus != OrderStatus.PENDING_PAYMENT;

     } catch (Exception e) {
         log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
         return false;
     }
 }

